import type { Transaction } from './transaction.entity';

/**
 * A named place where a User's money sits, holding one Currency (epic: Shared Domain Entities → Wallet).
 * The Balance is not a field — it is derived on read, never stored.
 */
export interface Wallet {
  /** UUID, generated by Postgres. */
  id: string;
  /** The owner. */
  userId: string;
  /** Trimmed, 1–60 characters. Not unique. */
  name: string;
  /** ISO-4217 code of a supported Currency, fixed at creation (AD-2). */
  currency: string;
  /** In minor units of `currency`; may be zero or negative — an Opening Balance is not Income. */
  openingBalanceMinor: bigint;
  /**
   * When the owner archived the Wallet (Postgres time); null while it is active. An Archived Wallet accepts no new
   * Transaction, keeps its history, still counts in Currency Totals — and stays archived: there is no unarchive.
   */
  archivedAt: Date | null;
  createdAt: Date;
  updatedAt: Date;
}

/** What Ledger needs to store a Wallet; the id and timestamps are generated by Postgres, a new Wallet is active. */
export interface NewWallet {
  userId: string;
  name: string;
  currency: string;
  openingBalanceMinor: bigint;
}

/** A Wallet with its Balance, derived by the database on every read: Opening Balance + Σ income − Σ expense. */
export interface WalletWithBalance {
  wallet: Wallet;
  /** In minor units of the Wallet's Currency; may be negative, may exceed 15 digits. */
  balanceMinor: bigint;
}

/** A Wallet with its Balance and its Transactions, read together from one consistent snapshot. */
export interface WalletDetail extends WalletWithBalance {
  /** Newest `occurredOn` first, ties by newest `createdAt`, then `id` descending. */
  transactions: Transaction[];
}

/** What a rename and/or an archive changes: applied together or not at all. At least one of the two is asked for. */
export interface WalletChange {
  /** The new, already trimmed name; null leaves the name as it is. */
  name: string | null;
  /** True archives the Wallet; false leaves it as it is (an Archived Wallet cannot be made active again). */
  archive: boolean;
}
